# =========================================================================== parsing
def _s(v: Any) -> str:
    s = str(v).strip()
    while len(s) > 1 and s[0] == s[-1] and s[0] in "'\"":
        s = s[1:-1].strip()
    return s


def _k(v: Any) -> str:
    return _s(v).upper()


def _off(text: str) -> timezone:
    t = _s(text)
    sign = -1 if t[0] == "-" else 1
    hh, mm = t.lstrip("+-").split(":")
    return timezone(sign * timedelta(hours=int(hh), minutes=int(mm)))


def _iso(t: datetime) -> str:
    return t.astimezone(Z).strftime("%Y-%m-%dT%H:%M:%SZ")


def _utc(text: str) -> datetime:
    return datetime.fromisoformat(_s(text).replace("Z", "+00:00")).astimezone(Z)


def _rhe(fr: Fraction) -> int:
    fl = fr.numerator // fr.denominator
    rem = fr - fl
    if rem > Fraction(1, 2) or (rem == Fraction(1, 2) and fl % 2):
        fl += 1
    return fl


def _d6(x: Any) -> str:
    if isinstance(x, Fraction):
        v = _rhe(x * U6)
        neg = v < 0
        v = abs(v)
        return ("-" if neg and v else "") + f"{v // U6}.{v % U6:06d}"
    r = f"{float(x):.6f}"
    return "0.000000" if r == "-0.000000" else r


def _e6(x: float) -> str:
    return f"{float(x):.6e}"


def _yes(v: str) -> bool:
    return _s(v).lower() in ("y", "yes", "true", "1")


def _rows(text: str, sep: str) -> list[dict[str, str]]:
    return list(csv.DictReader(io.StringIO(text.lstrip("\ufeff")), delimiter=sep))


def _yaml(text: str) -> tuple[dict[str, str], dict[str, list[dict[str, str]]]]:
    scal: dict[str, str] = {}
    seqs: dict[str, list[dict[str, str]]] = {}
    sect = ""
    item: dict[str, str] | None = None
    for raw in text.splitlines():
        if not raw.strip() or raw.lstrip().startswith("#"):
            continue
        if not raw.startswith((" ", "-")):
            key, _, val = raw.partition(":")
            if val.strip():
                scal[key.strip()] = _s(val)
            else:
                sect = key.strip()
                seqs.setdefault(sect, [])
            item = None
            continue
        body = raw.strip()
        if body.startswith("- "):
            key, _, val = body[2:].partition(":")
            item = {key.strip(): _s(val)}
            seqs.setdefault(sect, []).append(item)
        elif item is not None and ":" in body:
            key, _, val = body.partition(":")
            item[key.strip()] = _s(val)
    return scal, seqs


def _epoch(path: Path) -> date:
    with zipfile.ZipFile(path) as z:
        wb = ET.fromstring(z.read("xl/workbook.xml"))
    pr = wb.find(XNS + "workbookPr")
    return date(1904, 1, 1) if pr is not None and _s(pr.attrib.get("date1904", "0")).lower() in ("1", "true") else date(1899, 12, 30)


def _cell_dt(raw: str, epoch: date) -> datetime:
    t = _s(raw)
    if re.fullmatch(r"[0-9]+(\.[0-9]+)?", t):
        d = Decimal(t)
        whole = int(d)
        return datetime.combine(epoch, datetime.min.time()) + timedelta(days=whole, seconds=int((d - whole) * 86400))
    return datetime.fromisoformat(t)


def _sheet(path: Path, name: str) -> list[dict[str, str]]:
    rel = "{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id"
    with zipfile.ZipFile(path) as z:
        wb = ET.fromstring(z.read("xl/workbook.xml"))
        rels = {r.attrib["Id"]: r.attrib["Target"] for r in ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))}
        rid = next(s.attrib[rel] for s in wb.iter(XNS + "sheet") if s.attrib["name"] == name)
        sst = ["".join(t.text or "" for t in si.iter(XNS + "t")) for si in ET.fromstring(z.read("xl/sharedStrings.xml")).iter(XNS + "si")]
        ws = ET.fromstring(z.read("xl/" + rels[rid].lstrip("/").removeprefix("xl/")))
    grid = []
    for row in ws.iter(XNS + "row"):
        cells = {}
        for c in row.iter(XNS + "c"):
            col = re.match(r"[A-Z]+", c.attrib["r"]).group(0)
            if c.attrib.get("t") == "inlineStr":
                cells[col] = "".join(t.text or "" for t in c.iter(XNS + "t"))
                continue
            v = c.find(XNS + "v")
            if v is not None:
                cells[col] = sst[int(v.text)] if c.attrib.get("t") == "s" else v.text
        grid.append(cells)
    return grid


_TOK = re.compile(rb"\((?:\\.|[^\\)])*\)|<[0-9A-Fa-f\s]*>|\[|\]|[A-Za-z]+|[-+0-9.]+|/\S+")


def _pstr(t: bytes) -> str:
    if t[:1] == b"<":
        return bytes.fromhex(t[1:-1].decode().replace(" ", "").replace("\n", "")).decode("latin-1")
    return re.sub(rb"\\(.)", rb"\1", t[1:-1]).decode("latin-1")


def _pdf(path: Path) -> list[list[str]]:
    raw = path.read_bytes()
    out: list[list[str]] = []
    for m in re.finditer(rb"<<([^<>]*)>>\s*stream\r?\n", raw):
        ln = re.search(rb"/Length\s+(\d+)", m.group(1))
        if ln is None:
            continue
        body = raw[m.end():m.end() + int(ln.group(1))]
        if b"FlateDecode" in m.group(1):
            body = zlib.decompress(body)
        pos: tuple[float, float] = (0.0, 0.0)
        operands: list[Any] = []
        cells: dict[float, list[tuple[float, str]]] = {}
        arr: list[str] | None = None
        for t in _TOK.findall(body):
            if t == b"[":
                arr = []
            elif t == b"]":
                operands.append("".join(arr or []))
                arr = None
            elif arr is not None:
                if t[:1] in (b"(", b"<"):
                    arr.append(_pstr(t))
            elif t[:1] in (b"(", b"<"):
                operands.append(_pstr(t))
            elif t == b"Tm":
                pos = (float(operands[-1]), float(operands[-2]))
                operands = []
            elif t in (b"Tj", b"TJ"):
                cells.setdefault(pos[0], []).append((pos[1], operands[-1]))
                operands = []
            elif t in (b"BT", b"ET", b"Tf"):
                operands = []
            else:
                operands.append(t.decode("latin-1"))
        for yv in sorted(cells, reverse=True):
            out.append([c for _, c in sorted(cells[yv])])
    return out


def _memo(path: Path) -> dict[str, list[dict[str, str]]]:
    tabs: dict[str, list[list[str]]] = {}
    cur = None
    for cells in _pdf(path):
        if len(cells) == 1:
            m = re.match(r"Table ([A-Z]-\d+)", cells[0].strip())
            if m:
                cur = m.group(1)
                tabs.setdefault(cur, [])
            continue
        if cur is not None and len(cells) >= 3:
            tabs[cur].append([c.strip() for c in cells])
    res = {}
    for key, rows in tabs.items():
        if not rows:
            continue
        head = rows[0]
        res[key] = [dict(zip(head, r)) for r in rows[1:] if r != head]
    return res


_XF = {
    "x_jsonl": ("eid", "ts", "unit", "exp", "arm", "st", "rev"),
    "x_csv": ("exposure_id", "logged_at", "unit_token", "experiment", "variant", "status", "revision"),
    "x_tsv": ("exposure", "ms", "unit", "exp", "variant", "state", "rev"),
    "x_psv": ("exposure", "local_time", "unit", "experiment", "variant", "status", "rev"),
    "x_xml": ("id", "t", "u", "e", "v", "s", "r"),
    "x_yaml": ("id", "ts", "unit", "experiment", "variant", "status", "rev"),
    "x_json": ("exposureId", "epochMillis", "unitToken", "experimentKey", "variantKey", "state", "revision"),
    "o_csv": ("order_id", "placed_at", "customer", "currency", "amount", "order_status", "revision"),
}
_SEP = {"x_csv": ",", "x_tsv": "\t", "x_psv": "|", "o_csv": ","}


def _feed(path: Path, layout: str) -> list[tuple[str, ...]]:
    out: list[tuple] = []
    if layout in ("x_sqlite", "o_db"):
        con = sqlite3.connect(f"file:{path}?mode=ro", uri=True)
        q = ("SELECT exposure_id, epoch_s, unit_token, experiment, variant, status, revision FROM exposure" if layout == "x_sqlite"
             else "SELECT oid, ep, uid, ccy, amt, st, rv FROM ord")
        out = list(con.execute(q))
        con.close()
        return [tuple(str(x) for x in r) for r in out]
    text = path.read_text(encoding="utf-8")
    if layout in _SEP:
        out = [tuple(r[f] for f in _XF[layout]) for r in _rows(text, _SEP[layout])]
    elif layout == "x_jsonl":
        out = [tuple(o[f] for f in _XF[layout]) for o in map(json.loads, filter(str.strip, text.splitlines()))]
    elif layout == "x_ndjson":
        for o in map(json.loads, filter(str.strip, text.splitlines())):
            out.append((o["event"]["id"], o["at"]["epoch"], o["subject"]["unit"], o["assign"]["experiment"], o["assign"]["variant"],
                        o["state"], o["event"]["rev"]))
    elif layout == "x_txt":
        cuts = [(0, 12), (12, 26), (26, 37), (37, 53), (53, 77), (77, 78), (78, 81)]
        out = [tuple(ln[a:b] for a, b in cuts) for ln in text.splitlines() if ln.strip() and not ln.startswith("#")]
    elif layout == "x_xml":
        out = [tuple(e.attrib[f] for f in _XF[layout]) for e in ET.fromstring(text).iter("x")]
    elif layout == "x_yaml":
        out = [tuple(i[f] for f in _XF[layout]) for i in _yaml(text)[1].get("records", [])]
    elif layout == "x_json":
        out = [tuple(o[f] for f in _XF[layout]) for o in json.loads(text)["export"]["rows"]]
    elif layout == "o_xml":
        for e in ET.fromstring(text).iter("order"):
            g = {c.tag: c.text or "" for c in e}
            out.append((g["id"], g["at"], g["customer"], g["ccy"], g["minor"], g["st"], g["rev"]))
    elif layout == "o_yml":
        for i in _yaml(text)[1].get("", []):
            amt, ccy = i["money"].split()
            out.append((i["order"], i["local"], i["cust"], ccy, amt, i["s"], i["rev"]))
    elif layout == "o_json":
        out = [(k, o["ms"], o["u"], o["c"], o["a"], o["s"], o["v"]) for k, o in json.loads(text).items()]
    else:
        raise ValueError(layout)
    return [tuple(str(x) for x in r) for r in out]


def _when(raw: str, conv: str, wall: timezone | None) -> datetime:
    s = _s(raw)
    if conv in ("epoch_s", "epoch_ms"):
        v = int(s)
        return datetime(1970, 1, 1, tzinfo=Z) + timedelta(seconds=v if conv == "epoch_s" else v // 1000)
    if conv == "compact_utc":
        return datetime(int(s[0:4]), int(s[4:6]), int(s[6:8]), int(s[8:10]), int(s[10:12]), int(s[12:14]), tzinfo=Z)
    if conv in ("iso_z", "iso_offset"):
        return _utc(s)
    return datetime.fromisoformat(s.replace(" ", "T")).replace(tzinfo=wall).astimezone(Z)


# =========================================================================== reference
def _state(root: Path, flip: str = "") -> dict[str, Any]:  # noqa: C901
    st: dict[str, Any] = {}
    scal, seqs = _yaml((root / "analysis_profile_w26.yml").read_text(encoding="utf-8"))
    st["scal"] = scal
    cutoff = _utc(scal["data_cutoff_utc"])
    pre = timedelta(days=int(scal["pre_period_days"]))
    rep = _off(scal["reporting_offset"])
    _, al = _yaml((root / "experiment_aliases.yaml").read_text(encoding="utf-8"))
    emap = {_k(i["alias"]): _k(i["canonical"]) for i in al["experiments"]}
    ex_of = lambda tok: emap.get(_k(tok), _k(tok))  # noqa: E731
    vmap = {(ex_of(i["experiment"]), _s(i["variant"]).lower()): _k(i["arm"]) for i in al["variants"]}
    links = {_k(r["from_id"]): (_k(r["linked_to"]), datetime.combine(date.fromisoformat(_s(r["linked_on"])), datetime.min.time(), Z))
             for r in _rows((root / "identity_links.psv").read_text(encoding="utf-8"), "|")}

    def unit(tok: str, at: datetime) -> tuple[str, int]:
        walk = [_k(tok)]
        while True:
            nxt = links.get(walk[-1])
            if nxt is None or (nxt[1] > at and flip != "ungated_links"):
                return walk[-1], len(walk) - 1
            if nxt[0] in walk:
                return min(walk[walk.index(nxt[0]):]), len(walk) - 1
            walk.append(nxt[0])

    st["links"], st["unit"] = links, unit
    scope = sorted({ex_of(i["experiment"]) for i in seqs.get("experiments_in_scope", [])})
    internal = {unit(i["unit"], cutoff)[0] for i in seqs.get("internal_units", [])}

    wbp = root / "experiment_workbook_w26.xlsx"
    ep = _epoch(wbp)
    fxname = _s(scal["fx_sheet"])
    st["fxname"] = fxname
    regname = _s(scal["registry_version"])
    st["regname"] = regname
    reg: dict[str, dict] = {}
    head = None
    for c in _sheet(wbp, regname):
        if (c.get("A") or "").strip() == "section":
            head = {k: v.strip() for k, v in c.items()}
            continue
        if head and (c.get("A") or "").strip() == "METRIC":
            g = {head[k]: (c.get(k) or "").strip() for k in head}
            na = lambda v: None if v in ("", "-") else v  # noqa: E731
            reg[g["metric"].lower()] = {"kind": g["kind"].lower(), "attribution_days": int(Decimal(g["attribution_days"])),
                                        "winsor_pct": na(g["winsor_pct"]), "cuped": _yes(g["cuped"]), "covariate": na(g["covariate"]),
                                        "role": g["role"].lower(), "higher_is_better": _yes(g["higher_is_better"]),
                                        "numerator": na(g["numerator"]), "denominator": na(g["denominator"])}
    exps: dict[str, dict] = {}
    grid = _sheet(wbp, "Experiments")
    hd = {k: v.strip() for k, v in grid[0].items()}
    for c in grid[1:]:
        g = {hd[k]: (c.get(k) or "").strip() for k in hd}
        if g.get("experiment"):
            exps[_k(g["experiment"])] = {"tzt": _s(g["tz_offset"]), "tz": _off(g["tz_offset"]), "s": _cell_dt(g["start_local"], ep),
                                         "e": _cell_dt(g["end_local"], ep), "primary": g["primary_metric"].lower(),
                                         "team": _s(g["owner_team"]).lower(), "arms": {}}
    grid = _sheet(wbp, "Allocation")
    hd = {k: v.strip() for k, v in grid[0].items()}
    for c in grid[1:]:
        g = {hd[k]: (c.get(k) or "").strip() for k in hd if k in c}
        if g.get("arm"):
            exps[_k(g["experiment"])]["arms"][_k(g["arm"])] = (g["role"].lower(), _s(g["weight_pct"]))
    minor = {}
    for c in _sheet(wbp, "Currencies")[1:]:
        if c.get("A", "").strip():
            minor[c["A"].strip().upper()] = int(Decimal(c["B"].strip()))
    fx: dict[str, list[tuple[date, str, Fraction]]] = {}
    for c in _sheet(wbp, fxname):
        a = (c.get("A") or "").strip()
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}|[0-9]+(\.[0-9]+)?", a) and c.get("B"):
            fx.setdefault(c["B"].strip().upper(), []).append((_cell_dt(a, ep).date(), c["C"].strip().upper(), Fraction(Decimal(c["D"].strip()))))
    for v in fx.values():
        v.sort()

    memo = _memo(root / "stats_governance_memo_w26.pdf")
    par = {r["parameter"]: r["value"] for r in memo["P-1"]}
    st["par"] = par
    alpha, bhq, srma = float(par["alpha_two_sided"]), float(par["bh_q"]), float(par["srm_alpha"])
    xr = {}
    for r in memo["X-1"]:
        if r["status"].upper() == "IN FORCE":
            xr[ex_of(r["experiment"])] = (r["ruling"].upper(), r["revised_end_local"])
    ur = {}
    for r in memo["U-1"]:
        if r["status"].upper() == "IN FORCE":
            ur[unit(r["unit_token"], cutoff)[0]] = r["ruling"].upper()
    cap = {_s(r["owner_team"]).lower(): int(_s(r["max_ship"])) for r in memo.get("C-0" if flip == "withdrawn_capacity" else "C-1", [])}
    amends = [r for r in memo["A-1"] if r["status"].upper() == "IN FORCE"]
    st["amend_status"] = {r["amendment_id"]: r["status"].upper() for r in memo["A-1"]}

    acct: dict[str, str] = {}
    for r in _rows((root / "unit_registry_legacy.tsv").read_text(encoding="utf-8"), "\t"):
        if not (_k(r["UNIT"]) in links and links[_k(r["UNIT"])][1] <= cutoff):
            acct[_k(r["UNIT"])] = r["AccountType"].strip().lower()
    for r in _rows((root / "unit_registry_main.csv").read_text(encoding="utf-8"), ","):
        if not (_k(r["unit_id"]) in links and links[_k(r["unit_id"])][1] <= cutoff):
            acct[_k(r["unit_id"])] = r["account_type"].strip().lower()

    def reason_of(u: str) -> str | None:
        if u not in acct:
            return "UNREGISTERED"
        if ur.get(u) == "EXCLUDE":
            return "RULING_EXCLUDED"
        if u in internal:
            return "INTERNAL_LIST"
        t = "human" if ur.get(u) == "REINSTATE" else acct[u]
        return None if t == "human" else t.upper()

    for code, e in exps.items():
        rl = xr.get(code, ("NONE", "-"))
        e["ruling"] = rl[0]
        e["start"] = e["s"].replace(tzinfo=e["tz"]).astimezone(Z)
        e["end"] = (datetime.fromisoformat(rl[1]) if rl[0] in ("EXTENDED", "SHORTENED") else e["e"]).replace(tzinfo=e["tz"]).astimezone(Z)
    an = [c for c in scope if exps[c]["ruling"] != "ABORTED"]
    st.update(exps=exps, scope=scope, an=an)

    cfgs: dict[str, dict[str, dict]] = {}
    seq_am = [r for r in amends if _k(r["experiment"]) == "ALL"] + [r for r in amends if _k(r["experiment"]) != "ALL"]
    seq_am = sorted([r for r in seq_am if _k(r["experiment"]) == "ALL"], key=lambda r: r["amendment_id"]) + \
        sorted([r for r in seq_am if _k(r["experiment"]) != "ALL"], key=lambda r: r["amendment_id"])
    for code in an:
        cf = {m: dict(v, amendments=[]) for m, v in reg.items()}
        for r in seq_am:
            if _k(r["experiment"]) != "ALL" and ex_of(r["experiment"]) != code:
                continue
            m = r["metric"].strip().lower()
            if m not in cf:
                continue
            f, v = r["field"].strip(), r["new_value"].strip()
            if f == "winsor_pct":
                cf[m]["winsor_pct"] = v
            elif f == "attribution_days":
                cf[m]["attribution_days"] = int(v)
            elif f == "cuped":
                cf[m]["cuped"] = _yes(v)
            cf[m]["amendments"].append(r["amendment_id"])
        for v in cf.values():
            v["cuped"] = bool(v["cuped"]) and v["covariate"] is not None
        cfgs[code] = cf
    st["cfgs"] = cfgs

    # ------------------------------------------------------------- feeds
    cat = json.loads((root / "ingest_catalog_w26.json").read_text(encoding="utf-8"))
    lineage: dict[str, dict] = {}
    ver: dict[str, dict[str, list]] = {"exposure": {}, "order": {}}
    for sh in cat["shards"]:
        fn, lay, conv, stream = sh["file"], sh["layout"], sh["ts_convention"], sh["stream"]
        sc = {a.strip(): b for a, b in sh["status_codes"].items()}
        rows = _feed(root / fn, lay)
        lineage[fn] = {"stream": stream, "rows": len(rows), "kept": 0}
        for i, r in enumerate(rows):
            if stream == "exposure":
                code = ex_of(r[3])
                wall = exps[code]["tz"] if code in exps else rep
                rec = (_k(r[0]), int(_s(r[6])), sc[r[5].strip()] == "LIVE", _when(r[1], conv, wall), r[2], code, _s(r[4]).lower(), fn)
            else:
                ccy = r[3].strip().upper()
                if sh["amount_unit"] == "minor":
                    mn = int(_s(r[4]))
                else:
                    mn = Decimal(_s(r[4])).scaleb(minor[ccy])
                    if mn != mn.to_integral_value():
                        raise ValueError("fractional minor amount")
                    mn = int(mn)
                rec = (_k(r[0]), int(_s(r[6])), sc[r[5].strip()] == "PLACED", _when(r[1], conv, rep), r[2], ccy, mn, fn)
            ver[stream].setdefault(rec[0], []).append(rec)
    win: dict[str, dict[str, tuple]] = {"exposure": {}, "order": {}}
    dd: dict[str, dict[str, int]] = {}
    for stream, vs in ver.items():
        dups = dead = rows_n = 0
        for key, lst in vs.items():
            rows_n += len(lst)
            dups += len(lst) - 1
            top = sorted(lst, key=lambda r: -r[1])[0]
            if top[2]:
                win[stream][key] = top
                lineage[top[7]]["kept"] += 1
            else:
                dead += 1
        dd[stream] = {"rows_read": rows_n, "duplicate_rows_dropped": dups, ("voided" if stream == "exposure" else "cancelled"): dead,
                      "live": len(win[stream])}
    oos = unm = 0
    xs = []
    for rec in win["exposure"].values():
        if rec[5] not in scope:
            oos += 1
            continue
        arm = vmap.get((rec[5], rec[6]))
        if arm is None:
            unm += 1
            continue
        xs.append((rec, arm))
    dd["exposure"].update(out_of_scope=oos, unmapped_variant=unm)
    st["dedup"], st["lineage"] = dd, lineage

    # ------------------------------------------------------------- participants
    grp: dict[tuple[str, str], list] = {}
    for rec, arm in xs:
        code = rec[5]
        if code not in an or rec[3] >= exps[code]["end"]:
            continue
        grp.setdefault((code, unit(rec[4], rec[3])[0]), []).append((rec[3], arm))
    parts: dict[str, dict[str, tuple]] = {c: {} for c in an}
    excl = []
    for (code, u) in sorted(grp):
        lst = grp[(code, u)]
        why = reason_of(u)
        arms = sorted({a for _, a in lst})
        fe = min(t for t, _ in lst)
        if why is None and len(arms) != 1:
            why = "CROSSOVER"
        if why is None and fe < exps[code]["start"]:
            why = "PRE_START"
        if why:
            excl.append({"experiment": code, "reason": why, "unit_id": u})
        else:
            parts[code][u] = (arms[0], fe, len(lst))
    st["parts"], st["excl"] = parts, excl

    # ------------------------------------------------------------- refunds and valuation
    jr = []
    for o in (json.loads(x) for x in (root / "refund_journal.jsonl").read_text(encoding="utf-8").splitlines() if x.strip()):
        jr.append((int(o["seq"]), "jsonl", o["status"], _k(o["refund_id"]), _k(o["order_id"]), int(o["amount_minor"]), _utc(o["posted_utc"]),
                   _s(o.get("kind") or "refund").lower()))
    for e in ET.fromstring((root / "refund_journal_late.xml").read_text(encoding="utf-8")).iter("refund"):
        jr.append((int(e.attrib["seq"]), "xml", e.attrib["status"], _k(e.findtext("id")), _k(e.findtext("order")), int(e.findtext("minor").strip()),
                   _utc(e.findtext("posted")), _s(e.attrib.get("kind") or "refund").lower()))
    jr.sort()
    applied: dict[str, tuple[str, int]] = {}
    rlog = []
    for seq, jn, stt, rid, oid, amt, posted, kind in jr:
        if stt.strip().lower() != "posted":
            continue
        if posted >= cutoff:
            oc = "AFTER_CUTOFF"
        elif oid not in ver["order"]:
            oc = "NO_ORDER"
        elif oid not in win["order"]:
            oc = "ORDER_CANCELLED"
        elif kind == "reversal":
            oc = "REVERSED" if applied.pop(rid, None) is not None else "NOTHING_TO_REVERSE"
        else:
            oc = "REPLACED" if rid in applied else "APPLIED"
            applied[rid] = (oid, amt)
        rlog.append({"journal": jn, "kind": kind, "order_id": oid, "outcome": oc, "refund_id": rid, "seq": seq})
    st["rlog"] = rlog
    refd: dict[str, int] = {}
    for oid, amt in applied.values():
        refd[oid] = refd.get(oid, 0) + amt

    def usd(mn: int, ccy: str, day: date) -> tuple[int, str]:
        amt = Fraction(mn) / 10 ** minor[ccy]
        if ccy == "USD":
            return _rhe(amt * U6), ""
        def pick(c: str) -> tuple[date, str, Fraction]:
            lst = fx[c]
            return lst[bisect.bisect_right([x[0] for x in lst], day) - 1]

        d0, quote, rate = pick(ccy)
        if quote == "UNIT_PER_EUR":
            _, eq, er = pick("EUR")
            amt, rate, quote = amt / rate, er, eq
        return _rhe((amt * rate if quote == "USD_PER_UNIT" else amt / rate) * U6), d0.isoformat()

    val = []
    uo: dict[str, list] = {}
    for oid in sorted(win["order"]):
        rec = win["order"][oid]
        if rec[3] >= cutoff:
            continue
        u = unit(rec[4], rec[3])[0]
        net = max(0, rec[6] - refd.get(oid, 0))
        nu, fd = usd(net, rec[5], rec[3].date())
        ru, _ = usd(rec[6] - net, rec[5], rec[3].date())
        val.append([oid, u, rec[5], rec[6], refd.get(oid, 0), net, fd, _d6(Fraction(nu, U6)), _d6(Fraction(ru, U6))])
        uo.setdefault(u, []).append((rec[3], nu, ru, net > 0))
    st["val"] = val
    st["usd_total"] = sum((Fraction(int(r[7].replace(".", "")), U6) for r in val), Fraction(0))

    def wv(u: str, a: datetime, b: datetime, what: str) -> int:
        evs = [x for x in uo.get(u, []) if a <= x[0] < b]
        if what in ("conv7", "pre_conv"):
            return 1 if any(x[3] for x in evs) else 0
        if what in ("rev14", "pre_rev"):
            return sum(x[1] for x in evs)
        if what in ("ord14", "pre_ord"):
            return sum(1 for x in evs if x[3])
        if what == "rfd14":
            return sum(x[2] for x in evs)
        raise ValueError(what)

    # ------------------------------------------------------------- metrics
    def mom(pairs: list[tuple[int, int]]) -> tuple:
        n = len(pairs)
        return (n, sum(y for y, _ in pairs), sum(x for _, x in pairs), sum(y * y for y, _ in pairs), sum(x * x for _, x in pairs),
                sum(x * y for y, x in pairs))

    def cov(n: int, a: int, b: int, ab: int) -> Fraction:
        return Fraction(n * ab - a * b, n * (n - 1))

    caps, cup, arms_st = [], {}, {}
    for code in an:
        e = exps[code]
        arms = sorted(a for a, (r, _) in e["arms"].items() if r != "holdout")
        for m in sorted(cfgs[code]):
            c = cfgs[code][m]
            h = timedelta(days=c["attribution_days"])
            us = [u for u in sorted(parts[code]) if parts[code][u][0] in arms and parts[code][u][1] + h <= cutoff]
            sc = U6 if (c["kind"] == "ratio" or m in ("rev14", "rfd14")) else 1
            data = {}
            for u in us:
                fe = parts[code][u][1]
                if c["kind"] == "ratio":
                    data[u] = [wv(u, fe, fe + h, c["numerator"]), wv(u, fe, fe + h, c["denominator"])]
                else:
                    data[u] = [wv(u, fe, fe + h, m), wv(u, fe - pre, fe, c["covariate"]) if c["cuped"] else 0]
            if c["kind"] == "mean" and c["winsor_pct"] is not None and us:
                pc = Decimal(c["winsor_pct"])

                def nr(col: int) -> int:
                    srt = sorted(v[col] for v in data.values())
                    pos = int((pc * len(srt) / 100).to_integral_value(rounding="ROUND_CEILING"))
                    return srt[max(pos, 1) - 1]

                cy = nr(0)
                cx = nr(1) if c["cuped"] else None
                caps.append([code, m, c["winsor_pct"], len(us), _d6(Fraction(cy, sc)), "" if cx is None else _d6(Fraction(cx, sc)),
                             sum(1 for v in data.values() if v[0] > cy)])
                for v in data.values():
                    v[0] = min(v[0], cy)
                    if cx is not None:
                        v[1] = min(v[1], cx)
            n, sy, sx, syy, sxx, sxy = mom([tuple(v) for v in data.values()])
            th, mx = Fraction(0), Fraction(0)
            if c["cuped"]:
                vx = cov(n, sx, sx, sxx)
                th = cov(n, sx, sy, sxy) / vx if vx else Fraction(0)
                if flip != "unrounded_theta":
                    th = Fraction(_rhe(th * U6), U6)
                mx = Fraction(sx, n)
                vy = cov(n, sy, sy, syy)
                va = vy - 2 * th * cov(n, sx, sy, sxy) + th * th * vx
                cup.setdefault(code, {})[m] = {"mean_x": _d6(mx / sc), "theta": _d6(th),
                                               "variance_reduction_pct": _d6(100 * (1 - va / vy)) if vy else None}
            for a in arms:
                n, sy, sx, syy, sxx, sxy = mom([tuple(data[u]) for u in us if parts[code][u][0] == a])
                if c["kind"] == "ratio":
                    my, mxa = Fraction(sy, n), Fraction(sx, n)
                    r = my / mxa
                    v = (cov(n, sy, sy, syy) / mxa ** 2 - 2 * my * cov(n, sx, sy, sxy) / mxa ** 3 + my ** 2 * cov(n, sx, sx, sxx) / mxa ** 4) / n
                    arms_st[(code, a, m)] = {"n": n, "raw": r / sc, "adj": r / sc, "var": v / sc ** 2}
                else:
                    raw = Fraction(sy, n)
                    adj = raw - th * (Fraction(sx, n) - mx)
                    v = cov(n, sy, sy, syy) - 2 * th * cov(n, sx, sy, sxy) + th * th * cov(n, sx, sx, sxx)
                    arms_st[(code, a, m)] = {"n": n, "raw": raw / sc, "adj": adj / sc, "var": v / sc ** 2}
    st["caps"], st["cup"], st["arms"] = caps, cup, arms_st

    # ------------------------------------------------------------- tests
    zc = NormalDist().inv_cdf(1 - alpha / 2)
    srm = {}
    for code in an:
        e = exps[code]
        cnt = {a: sum(1 for p in parts[code].values() if p[0] == a) for a in e["arms"]}
        N = sum(cnt.values())
        ex_ = {a: Fraction(N) * Fraction(Decimal(w)) / 100 for a, (_, w) in e["arms"].items()}
        if flip == "even_split":
            ex_ = {a: Fraction(N, len(e["arms"])) for a in e["arms"]}
        chi = sum(((cnt[a] - ex_[a]) ** 2 / ex_[a] for a in e["arms"]), Fraction(0))
        dof = len(e["arms"]) - 1
        cf = float(chi)
        if dof == 1:
            p = math.erfc(math.sqrt(cf / 2))
        elif dof == 2:
            p = math.exp(-cf / 2)
        else:
            p = math.erfc(math.sqrt(cf / 2)) + math.sqrt(2 * cf / math.pi) * math.exp(-cf / 2)
        srm[code] = {"cnt": cnt, "exp": ex_, "chi": chi, "dof": dof, "p": p, "fail": p < srma}
    st["srm"] = srm
    tests = []
    for code in an:
        e = exps[code]
        ctl = [a for a, (r, _) in e["arms"].items() if r == "control"][0]
        for a in sorted(x for x, (r, _) in e["arms"].items() if r == "treatment"):
            for m in sorted(cfgs[code]):
                c = cfgs[code][m]
                A, B = arms_st[(code, ctl, m)], arms_st[(code, a, m)]
                diff = B["adj"] - A["adj"]
                var = B["var"] + A["var"] if c["kind"] == "ratio" else B["var"] / B["n"] + A["var"] / A["n"]
                se = math.sqrt(float(var))
                z = float(diff) / se
                p = math.erfc(abs(z) / math.sqrt(2))
                tests.append({"exp": code, "arm": a, "m": m, "role": "primary" if m == e["primary"] else c["role"], "A": A, "B": B,
                              "diff": diff, "se": se, "z": z, "p": p, "lo": float(diff) - zc * se, "hi": float(diff) + zc * se,
                              "base": A["raw"], "c": c, "q": None, "sig": None})
    fam = sorted((t for t in tests if t["role"] == "primary" and not srm[t["exp"]]["fail"]), key=lambda t: (t["p"], t["exp"], t["arm"]))
    mm = len(fam)
    run = 1.0
    for i in reversed(range(mm)):
        run = min(run, mm * fam[i]["p"] / (i + 1), 1.0)
        fam[i]["q"] = run
    for t in tests:
        if t["role"] == "primary":
            t["sig"] = "" if srm[t["exp"]]["fail"] else ("Y" if t["q"] <= bhq else "N")
        else:
            t["sig"] = "Y" if t["p"] < alpha else "N"
    st["tests"], st["fam"] = tests, fam
    gr = []
    for t in tests:
        if t["c"]["role"] != "guardrail":
            continue
        M = Fraction(Decimal(par["guardrail_margin_pct." + t["m"]]))
        lift = 100 * t["diff"] / t["base"]
        hib = t["c"]["higher_is_better"]
        br = t["p"] < alpha and ((t["diff"] < 0 and lift < -M) if hib else (t["diff"] > 0 and lift > M))
        gr.append({"t": t, "lift": lift, "lo": 100 * t["lo"] / float(t["base"]), "hi": 100 * t["hi"] / float(t["base"]),
                   "M": par["guardrail_margin_pct." + t["m"]], "br": br})
    st["gr"] = gr
    dec: dict[str, dict[str, dict]] = {}
    for code in scope:
        e = exps[code]
        dec[code] = {}
        for a in sorted(x for x, (r, _) in e["arms"].items() if r == "treatment"):
            if e["ruling"] == "ABORTED":
                dec[code][a] = {"decision": "ABORTED", "guardrail_breaches": [], "primary_metric": e["primary"], "q_value": None}
                continue
            pt = [t for t in tests if t["exp"] == code and t["arm"] == a and t["role"] == "primary"][0]
            brs = sorted(g["t"]["m"] for g in gr if g["t"]["exp"] == code and g["t"]["arm"] == a and g["br"])
            better = pt["diff"] > 0 if pt["c"]["higher_is_better"] else pt["diff"] < 0
            if srm[code]["fail"]:
                d = "INVALID_SRM"
            elif brs:
                d = "NO_SHIP_GUARDRAIL"
            elif pt["sig"] == "Y":
                d = "SHIP" if better else "NO_SHIP"
            else:
                d = "INCONCLUSIVE"
            dec[code][a] = {"decision": d, "guardrail_breaches": brs, "primary_metric": e["primary"],
                            "q_value": None if pt["q"] is None else _e6(pt["q"])}
    ships: dict[str, list[tuple[float, str, str]]] = {}
    for code in scope:
        for a, d in dec[code].items():
            if d["decision"] == "SHIP":
                q = [t["q"] for t in tests if t["exp"] == code and t["arm"] == a and t["role"] == "primary"][0]
                ships.setdefault(exps[code]["team"], []).append((q, code, a))
    deferred = []
    for team in sorted(ships):
        if team not in cap or flip == "first_pass":
            continue
        for _, code, a in sorted(ships[team])[cap[team]:]:
            dec[code][a]["decision"] = "SHIP_DEFERRED"
            deferred.append(f"{code}/{a}")
    st["deferred"] = sorted(deferred)
    st["dec"] = dec
    pub = {}
    for r in _rows((root / _s(scal["published_readout"])).read_text(encoding="utf-8"), ","):
        if _k(r["cut"]) == "ALL":
            pub[(_k(r["experiment"]), _k(r["arm"]), r["metric"].strip().lower())] = (r["diff"].strip(), _k(r["significant"]))
    st["pub"] = pub
    return st


def _tbl(rows: list[list[Any]], sep: str) -> str:
    return "".join(sep.join(str(c) for c in r) + "\n" for r in rows)


def _js(o: Any) -> str:
    return json.dumps(o, sort_keys=True) + "\n"


def _render(st: dict[str, Any]) -> dict[str, str]:  # noqa: C901
    f: dict[str, str] = {}
    rows = [["experiment", "arm", "metric", "role", "n_control", "n_treatment", "mean_control", "mean_treatment", "diff", "lift_pct", "se", "z",
             "p_value", "ci_low", "ci_high", "q_value", "significant"]]
    for t in st["tests"]:
        rows.append([t["exp"], t["arm"], t["m"], t["role"], t["A"]["n"], t["B"]["n"], _d6(t["A"]["adj"]), _d6(t["B"]["adj"]), _d6(t["diff"]),
                     _d6(100 * t["diff"] / t["base"]) if t["base"] else "", _d6(t["se"]), _d6(t["z"]), _e6(t["p"]), _d6(t["lo"]), _d6(t["hi"]),
                     "" if t["q"] is None else _e6(t["q"]), t["sig"]])
    f["readout.csv"] = _tbl(rows, ",")
    rows = [["experiment", "arm", "metric", "n", "raw_mean", "adj_mean", "variance"]]
    rows += [[c, a, m, s["n"], _d6(s["raw"]), _d6(s["adj"]), _d6(s["var"])] for (c, a, m), s in sorted(st["arms"].items())]
    f["arm_metrics.tsv"] = _tbl(rows, "\t")
    f["winsor_caps.psv"] = _tbl([["experiment", "metric", "winsor_pct", "n_pooled", "cap", "covariate_cap", "capped_units"]] + sorted(st["caps"]), "|")
    f["cuped.json"] = _js(st["cup"])
    rows = [["experiment", "arm", "role", "weight_pct", "observed", "expected", "chi2", "dof", "p_value", "status"]]
    for code in st["an"]:
        s = st["srm"][code]
        for a in sorted(st["exps"][code]["arms"]):
            role, w = st["exps"][code]["arms"][a]
            rows.append([code, a, role, w, s["cnt"][a], _d6(s["exp"][a]), _d6(s["chi"]), s["dof"], _e6(s["p"]), "FAIL" if s["fail"] else "PASS"])
    f["srm_report.csv"] = _tbl(rows, ",")
    rows = [["rank", "experiment", "arm", "metric", "p_value", "q_value", "significant"]]
    rows += [[i + 1, t["exp"], t["arm"], t["m"], _e6(t["p"]), _e6(t["q"]), t["sig"]] for i, t in enumerate(st["fam"])]
    f["bh_family.csv"] = _tbl(rows, ",")
    rows = [["experiment", "arm", "metric", "lift_pct", "lift_ci_low", "lift_ci_high", "margin_pct", "breach"]]
    rows += [[g["t"]["exp"], g["t"]["arm"], g["t"]["m"], _d6(g["lift"]), _d6(g["lo"]), _d6(g["hi"]), g["M"], "Y" if g["br"] else "N"] for g in st["gr"]]
    f["guardrails.csv"] = _tbl(rows, ",")
    f["decisions.json"] = _js(st["dec"])
    rows = [["experiment", "unit_id", "arm", "first_exposure_utc", "exposures"]]
    for code in st["an"]:
        rows += [[code, u, p[0], _iso(p[1]), p[2]] for u, p in sorted(st["parts"][code].items())]
    f["unit_assignments.csv"] = _tbl(rows, ",")
    f["excluded_units.jsonl"] = "".join(_js(x) for x in st["excl"])
    cut = _utc(st["scal"]["data_cutoff_utc"])
    f["identity_resolution.csv"] = _tbl([["from_id", "unit_id", "hops"]] + [[a, *st["unit"](a, cut)] for a in sorted(st["links"])], ",")
    f["dedup_report.json"] = _js(st["dedup"])
    f["source_lineage.json"] = _js(st["lineage"])
    f["refund_outcomes.jsonl"] = "".join(_js(x) for x in st["rlog"])
    f["order_valuation.psv"] = _tbl([["order_id", "unit_id", "currency", "amount_minor", "refund_minor", "net_minor", "fx_date", "usd_net",
                                      "usd_refunded"]] + st["val"], "|")
    cfg: dict[str, Any] = {"registry_version": st["regname"], "fx_sheet": st["fxname"]}
    for code in st["an"]:
        cfg[code] = st["cfgs"][code]
    f["metric_config_used.json"] = _js(cfg)
    xml = [f'<portfolio id="{st["scal"]["portfolio_id"]}">']
    for code in st["scope"]:
        e = st["exps"][code]
        xml.append(f'<experiment code="{code}" tz_offset="{e["tzt"]}" owner_team="{e["team"]}" start_utc="{_iso(e["start"])}" end_utc="{_iso(e["end"])}" '
                   f'ruling="{e["ruling"]}" status="{"ABORTED" if e["ruling"] == "ABORTED" else "ANALYSED"}"/>')
    xml.append("</portfolio>")
    f["experiment_windows.xml"] = "\n".join(xml) + "\n"
    cnt: dict[str, int] = {}
    for v in st["dec"].values():
        for d in v.values():
            cnt[d["decision"]] = cnt.get(d["decision"], 0) + 1
    f["portfolio_summary.json"] = _js({"decisions": cnt, "deferred_arms": st["deferred"], "excluded_candidates": len(st["excl"]), "experiments_aborted": len(st["scope"]) - len(st["an"]),
                                       "experiments_analysed": len(st["an"]), "family_size": len(st["fam"]), "live_orders": len(st["val"]),
                                       "participants": sum(len(v) for v in st["parts"].values()), "portfolio_id": st["scal"]["portfolio_id"],
                                       "registry_version": st["regname"], "srm_failures": sum(1 for c in st["an"] if st["srm"][c]["fail"]),
                                       "usd_net_total": _d6(st["usd_total"])})
    cor = {(t["exp"], t["arm"], t["m"]): (_d6(t["diff"]), t["sig"] or "N") for t in st["tests"]}
    pub = st["pub"]
    rows = [["experiment", "arm", "metric", "published_diff", "corrected_diff", "published_significant", "corrected_significant", "status"]]
    for key in sorted(set(pub) | set(cor)):
        p, c = pub.get(key), cor.get(key)
        stt = "NEW" if p is None else "DROPPED" if c is None else ("FLIPPED" if p[1] != c[1] else "SAME")
        rows.append(list(key) + [p[0] if p else "", c[0] if c else "", p[1] if p else "", c[1] if c else "", stt])
    f["variance_vs_published.csv"] = _tbl(rows, ",")
    md = [f"# Portfolio {st['scal']['portfolio_id']} readout reconciliation", "", "| experiment | arm | published_decision | corrected_decision |",
          "|---|---|---|---|"]
    for code in st["scope"]:
        for a, d in sorted(st["dec"][code].items()):
            p = pub.get((code, a, st["exps"][code]["primary"]))
            pd = "MISSING" if p is None else ("SHIP" if Decimal(p[0]) > 0 else "NO_SHIP") if p[1] == "Y" else "INCONCLUSIVE"
            md.append(f"| {code} | {a} | {pd} | {d['decision']} |")
    f["reconciliation.md"] = "\n".join(md) + "\n"
    return f


def _once(k: str, build) -> Any:
    """Build the value for k exactly once. rewardkit runs checks in parallel threads, so a caller either
    builds the value while holding the key's lock or waits for it; nothing half-built is ever stored."""
    with _MEMO_GUARD:
        lock = _MEMO_LOCKS.setdefault(k, threading.Lock())
    with lock:
        if k not in _MEMO:
            _MEMO[k] = build()
        return _MEMO[k]


def _st(root: Path) -> dict[str, Any]:
    return _once("state:" + str(root), lambda: _state(root))


def derive(root: Path) -> dict[str, str]:
    return _once("derive:" + str(root), lambda: _render(_st(root)))


# =========================================================================== comparison
_NUM = re.compile(r"-?\d+(\.\d+)?(e[+-]\d+)?$")


def _canon(name: str, text: str) -> Any:
    if name.endswith(".json"):
        return json.loads(text)
    if name.endswith(".jsonl"):
        return [json.loads(ln) for ln in text.splitlines() if ln.strip()]
    if name.endswith(".xml"):
        root = ET.fromstring(text)
        return [root.tag, dict(root.attrib), [[c.tag, dict(c.attrib)] for c in root]]
    if name.endswith(".md"):
        out = []
        for ln in text.splitlines():
            ln = ln.strip()
            if ln.startswith("|"):
                out.append([c.strip() for c in ln.strip("|").split("|")])
            elif ln:
                out.append(" ".join(ln.split()))
        return out
    sep = {".csv": ",", ".tsv": "\t", ".psv": "|"}[Path(name).suffix]
    return [r for r in csv.reader(io.StringIO(text.lstrip("\ufeff")), delimiter=sep) if r]


def _eq(a: Any, b: Any) -> bool:
    if isinstance(a, dict) and isinstance(b, dict):
        return a.keys() == b.keys() and all(_eq(a[k], b[k]) for k in a)
    if isinstance(a, list) and isinstance(b, list):
        return len(a) == len(b) and all(_eq(x, y) for x, y in zip(a, b))
    if isinstance(a, bool) or isinstance(b, bool) or a is None or b is None:
        return a == b and type(a) is type(b)
    if isinstance(a, int) and isinstance(b, int):
        return a == b
    return type(a) is type(b) and a == b


def _same(name: str, got: str, want: str) -> bool:
    try:
        return _eq(_canon(name, got), _canon(name, want))
    except Exception:
        return False


def _seal(root: Path) -> None:
    for p in root.iterdir():
        p.chmod(0o644)
    root.chmod(0o755)
    root.parent.chmod(0o755)


def _shipped() -> Path:
    def build() -> Path:
        root = Path(tempfile.mkdtemp(prefix="ro-shipped-")) / "data"
        root.mkdir()
        for rel, blob in _SHIPPED_DATA.items():
            (root / rel).write_bytes(zlib.decompress(base64.b64decode(blob)))
        _seal(root)
        return root
    return _once("shipped", build)


def _mine(name: str) -> str | None:
    try:
        return (OUT / name).read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return None


def _exact(name: str) -> bool:
    got = _mine(name)
    return got is not None and _same(name, got, derive(_shipped())[name])


