    _Gwrite(data_dir / "readout_calendar.yaml", "\n".join(cal) + "\n")

    snapj = {"generated": "2026-08-31", "note": "client-side FX snapshot for dashboards (monthly flat, quote as stored)",
             "rates": [{"date": (date(2026, 9, 1) + timedelta(days=d)).isoformat(), "currency": c, "rate": f"{lvl:.4f}"}
                       for d in range(36) for c, _, _, lvl, _ in _GCCY],
             "minor_units": {c: 2 for c in _GMINOR}}
    _Gwrite(data_dir / "fx_rates_snapshot.json", json.dumps(snapj, indent=1) + "\n")

    dash = []
    for e in _GEXPS:
        for d in range(24):
            for m in ("conv7", "rev14", "ord14"):
                dash.append([e["code"], (date(2026, 9, 1) + timedelta(days=d)).isoformat(), m, f"{rng.uniform(-3, 6):.2f}", f"{rng.uniform(0.001, 0.9):.4f}"])
    _Gwrite(data_dir / "metric_dashboard_export.csv", _Gcsv_text(["experiment", "day_utc", "metric", "lift_pct", "p_value"], dash))

    symptoms = ["SRM alarm on promo banner", "bots counted in treatment", "JPY revenue off by 100x", "KWD orders look tiny", "CHF revenue off by the euro rate", "device exposures before the link date stitched",
                "reversed refunds still deducted", "two retention launches shipped together", "theta not rounded",
                "window starts at midnight UTC", "holdout counted as control", "cap computed per arm", "theta fitted per arm",
                "extended enrolment missing", "aborted test still in readout", "refunds after cutoff counted", "late refund journal ignored",
                "crossovers kept in first arm", "pre-start exposures counted", "weekend orders lost the FX rate", "INR rate not inverted"]
    tickets = []
