def _hx(code, owner, tz, start, end, primary, n, arms, eff, feature, **kw):
    d = dict(code=code, owner=owner, tz=tz, start=start, end=end, primary=primary, scope=kw.pop("scope", True), n=n,
             arms=arms, eff=eff, aliases=[feature, code.replace("-", ""), code.lower(), feature[:3] + "-" + feature[-3:]],
             feature=feature)
    d.update(kw)
    return d


