def _hcfg(name: str) -> tuple[int, dict]:
    c = copy.deepcopy(_HBASE)
    if name == "h_policy":
        c.update(registry_version="MR-6", fx_sheet="FX-R1", portfolio="WAVE-26Q4",
                 p1={"alpha_two_sided": "0.10", "bh_q": "0.10", "srm_alpha": "0.01",
                     "guardrail_margin_pct.aov14": "4.00", "guardrail_margin_pct.rfd14": "8.00"},
                 capacity={"retention": "2", "checkout": "0", "discovery": "1", "growth": "1"})
        return 71001, c
    if name == "h_fourarm":
        c.update(exps=copy.deepcopy(_HSET_B), capacity={"retention": "1", "growth": "0", "search": "1", "discovery": "1"})
        return 71002, c
    if name == "h_calendar":
        c.update(cutoff="2026-10-09T00:00:00Z", pre_period_days=21, reporting="+04:00", cycles=12, reversal_rate=0.12,
                 timed_link_frac=0.25)
        return 71003, c
    if name == "h_mixed":
        exps = copy.deepcopy(_HSET_B)
        for e in exps:
            if e["code"] == "EXP-2717":
                e["owner"] = "search"
        c.update(exps=exps, registry_version="MR-6", cutoff="2026-10-10T00:00:00Z", reporting="-02:30",
                 p1={"alpha_two_sided": "0.01", "bh_q": "0.10", "srm_alpha": "0.0001",
                     "guardrail_margin_pct.aov14": "1.50", "guardrail_margin_pct.rfd14": "15.00"},
                 capacity={"retention": "2", "growth": "1", "checkout": "1", "search": "1"})
        return 71004, c
    if name == "h_dense":
        c.update(cycles=15, late_link_frac=0.06, cutoff_link_frac=0.03, reversal_rate=0.15, boundary_links=40,
                 fx_sheet="FX-R1", capacity={"retention": "0", "pricing": "1", "search": "1"})
        return 71005, c
    if name == "h_shift":
        exps = copy.deepcopy(_HSET_B)
        for e in exps:
            if e["code"] == "EXP-2711":
                e["eff"] = {"TREAT_A": (1.30, 1.10, 1.0)}
            if e["code"] in ("EXP-2708", "EXP-2711"):
                e["owner"] = "retention"
        c.update(exps=exps, pre_period_days=7, reporting="+09:00", timed_link_frac=0.3,
                 capacity={"retention": "1", "checkout": "1", "growth": "1", "discovery": "0"})
        return 71006, c
    if name == "m_governance":
        c.update(p1={"alpha_two_sided": "0.10", "bh_q": "0.20", "srm_alpha": "0.0005",
                     "guardrail_margin_pct.aov14": "1.00", "guardrail_margin_pct.rfd14": "20.00"},
                 capacity={"retention": "2", "checkout": "1", "discovery": "1"})
        return None, c
    if name == "m_profile":
        c.update(registry_version="MR-6", fx_sheet="FX-R1")
        return None, c
    raise KeyError(name)


_HNAMES = ["h_policy", "h_fourarm", "h_calendar", "h_mixed", "h_dense", "h_shift", "m_governance", "m_profile"]


# =========================================================================== gate
CORE = ["unit_assignments.csv", "order_valuation.psv", "metric_config_used.json", "arm_metrics.tsv", "readout.csv",
        "srm_report.csv", "decisions.json"]
HELD_OUT = ["h_policy", "h_fourarm", "h_calendar", "h_mixed", "h_dense", "h_shift", "m_governance", "m_profile"]


def _core_exact(out: Path | None, root: Path) -> bool:
    if out is None:
        return False
    want = derive(root)
    for n in CORE:
        got = _out_text(out, n)
        if got is None or not _same(n, got, want[n]):
            return False
    return True


def _full_core() -> bool:
    """The spine: every core report is exact in /app/out for the shipped corpus and in the rerun on every held-out corpus."""
    return _once("full_core", lambda: all(_exact(n) for n in CORE) and all(
        _core_exact(_run(_held_out(name), name), _held_out(name)) for name in HELD_OUT))


# =========================================================================== corpora and runs
def _clone(dst: Path) -> Path:
    shutil.copytree(_shipped(), dst)
    _seal(dst)
    return dst


def _fresh(tag: str) -> Path:
    base = Path(tempfile.mkdtemp(prefix=f"ro-{tag}-"))
    base.chmod(0o755)
    return base / "data"


def _held_out(name: str) -> Path:
    def build() -> Path:
        seed, cfg = _hcfg(name)
        if seed is None:
            seed = SHIPPED_SEED
        root = _fresh(name)
        root.mkdir()
        for md in _shipped().glob("*.md"):
            shutil.copyfile(md, root / md.name)
        _Ggenerate(root, seed, cfg)
        _seal(root)
        return root
    return _once("corpus:" + name, build)


def _renamed() -> Path:
    def build() -> Path:
        root = _clone(_fresh("renamed"))
        cat_path = root / "ingest_catalog_w26.json"
        cat = json.loads(cat_path.read_text(encoding="utf-8"))
        for i, sh in enumerate(cat["shards"]):
            new = f"zq{i:02d}_{sh['file'][::-1].split('.', 1)[1][::-1]}.{sh['file'].rsplit('.', 1)[1]}"
            (root / sh["file"]).rename(root / new)
            sh["file"] = new
        cat_path.write_text(json.dumps(cat, indent=2) + "\n", encoding="utf-8")
        _seal(root)
        return root
    return _once("corpus:renamed", build)


def _root_only_tests_present() -> bool:
    try:
        status = Path("/tests").stat()
    except FileNotFoundError:
        return False
    return status.st_uid == 0 and (status.st_mode & 0o077) == 0


def _untrusted(command: list[str]) -> list[str]:
    if os.name == "posix" and os.geteuid() != 0 and _root_only_tests_present():
        raise RuntimeError("verifier must run as root to isolate submitted code from /tests")
    if os.name == "posix" and os.geteuid() == 0:
        return [*_SETPRIV, *command]
    return command


def _staged_program() -> Path | None:
    """Copy the delivered program into a verifier-owned directory, readable by the unprivileged runner."""
    def build() -> Path | None:
        if not PROGRAM.is_file():
            return None
        stage = Path(tempfile.mkdtemp(prefix="ro-prog-"))
        stage.chmod(0o755)
        staged = stage / "run_readout.py"
        shutil.copyfile(PROGRAM, staged)
        staged.chmod(0o755)
        return staged
    return _once("staged", build)


def _run(root: Path, tag: str) -> Path | None:
    def build() -> Path | None:
        prog = _staged_program()
        if prog is None:
            return None
        prog.chmod(0o755)
        work = Path(tempfile.mkdtemp(prefix=f"ro-run-{tag}-"))
        work.chmod(0o777)
        out = work / "out"
        try:
            proc = subprocess.Popen(_untrusted([sys.executable, str(prog), str(root), str(out)]), stdout=subprocess.DEVNULL,
                                    stderr=subprocess.DEVNULL, start_new_session=True)
            try:
                code = proc.wait(timeout=1200)
            finally:
                try:
                    os.killpg(proc.pid, 9)
                except OSError:
                    pass
        except (OSError, subprocess.SubprocessError):
            return None
        return out if code == 0 and out.is_dir() else None
    return _once("run:" + tag, build)


def _out_text(out: Path | None, name: str) -> str | None:
    if out is None:
        return None
    try:
        return (out / name).read_text(encoding="utf-8")
    except (OSError, UnicodeDecodeError):
        return None


def _all_exact(out: Path | None, root: Path) -> bool:
    if out is None:
        return False
    want = derive(root)
    for n in NAMES:
        got = _out_text(out, n)
        if got is None or not _same(n, got, want[n]):
            return False
    return True


def _held_out_exact(name: str) -> bool:
    if not _full_core():
        return False
    root = _held_out(name)
    return _all_exact(_run(root, name), root)


def _leaf(*names: str) -> bool:
    return _full_core() and all(_exact(n) for n in names)


def _flipped(flip: str, name: str) -> str:
    return _once(f"flip:{flip}", lambda: _render(_state(_shipped(), flip)))[name]


def _matches_flip(flip: str, name: str) -> bool:
    """True when the delivered report equals the named wrong reading and that reading differs from the truth."""
    got = _mine(name)
    want = derive(_shipped())[name]
    alt = _flipped(flip, name)
    return got is not None and not _same(name, alt, want) and _same(name, got, alt)


def _sources() -> str:
    try:
        return "\n".join(p.read_text(encoding="utf-8", errors="replace") for p in sorted(OUT.glob("*.py")))
    except OSError:
        return ""


def _safe(fn) -> bool:
    try:
        return bool(fn())
    except Exception:
        return False


def _csv_rows(name: str) -> list[dict[str, str]]:
    text = _mine(name) or ""
    sep = {".csv": ",", ".tsv": "\t", ".psv": "|"}[Path(name).suffix]
    return _rows(text, sep)


