@criterion(description="The program, all twenty contract reports and manifest.json exist under /app/out")
def deliverables_present(workspace: Path) -> bool:
    return PROGRAM.is_file() and all((OUT / n).is_file() for n in NAMES + ["manifest.json"])


@criterion(description="The program runs on a fresh copy of the corpus at another path and writes all twenty-one files")
def program_writes_contract_files(workspace: Path) -> bool:
    def chk() -> bool:
        out = _run(_clone(_fresh("copy")), "copy")
        return out is not None and all((out / n).is_file() for n in NAMES + ["manifest.json"])
    return _safe(chk)


@criterion(description="Every delimited report in /app/out starts with the exact header line of the output contract")
def delimited_headers_exact(workspace: Path) -> bool:
    def chk() -> bool:
        want = derive(_shipped())
        for n in NAMES:
            if n.endswith((".csv", ".tsv", ".psv")):
                got = _mine(n)
                if got is None or got.split("\n", 1)[0] != want[n].split("\n", 1)[0]:
                    return False
        return True
    return _safe(chk)


@criterion(description="The JSON reports in /app/out parse and carry the top-level keys the output contract names")
def json_report_keys(workspace: Path) -> bool:
    try:
        return _json_keys_ok()
    except (OSError, ValueError, TypeError, KeyError, AttributeError):
        return False


def _json_keys_ok() -> bool:
    if True:
        summ = json.loads(_mine("portfolio_summary.json") or "")
        dd = json.loads(_mine("dedup_report.json") or "")
        cfg = json.loads(_mine("metric_config_used.json") or "")
        want_s = json.loads(derive(_shipped())["portfolio_summary.json"])
        return (set(summ) == set(want_s) and set(dd) == {"exposure", "order"} and "registry_version" in cfg and "fx_sheet" in cfg
                and all(isinstance(json.loads(x), dict) for x in (_mine("refund_outcomes.jsonl") or "").splitlines()[:5]))


@criterion(description="manifest.json lists every other report in contract order with its true size and SHA-256 digest")
def manifest_consistent(workspace: Path) -> bool:
    try:
        man = json.loads((OUT / "manifest.json").read_text(encoding="utf-8"))
        if [x["name"] for x in man["files"]] != NAMES:
            return False
        for x in man["files"]:
            blob = (OUT / x["name"]).read_bytes()
            if x["bytes"] != len(blob) or x["sha256"] != hashlib.sha256(blob).hexdigest():
                return False
        return True
    except (OSError, ValueError, TypeError, KeyError):
        return False


@criterion(description="Every report in /app/out is UTF-8 text with LF line endings and a final newline")
def text_serialization(workspace: Path) -> bool:
    try:
        for n in NAMES + ["manifest.json"]:
            blob = (OUT / n).read_bytes()
            text = blob.decode("utf-8")
            if not text.endswith("\n") or "\r" in text:
                return False
        return True
    except (OSError, UnicodeDecodeError):
        return False


