# =========================================================================== negative checks (True when the cheat or wrong reading is present)
def _echoes_shipped() -> bool:
    root = _held_out("h_policy")
    want_v = derive(root)["readout.csv"]
    want_s = derive(_shipped())["readout.csv"]
    if _same("readout.csv", want_v, want_s):
        return False
    got = _out_text(_run(root, "h_policy"), "readout.csv")
    return got is not None and _same("readout.csv", got, want_s)


@criterion(description="The program ignores its input and replays the shipped readout on a held-out corpus")
def negative_hardcoded_sample_answers(workspace: Path) -> bool:
    # inverted: True only when the held-out rerun reproduces the shipped readout although its truth differs
    return _safe(_echoes_shipped)


@criterion(description="The program is exact on a copy of the shipped corpus and wrong once only the shard file names change")
def negative_filename_dependent_behaviour(workspace: Path) -> bool:
    # inverted: True only when renaming shards (and their catalog entries) alone breaks an otherwise exact program
    def chk() -> bool:
        if _echoes_shipped():
            return False
        if not _all_exact(_run(_clone(_fresh("copy")), "copy"), _shipped()):
            return False
        return not _all_exact(_run(_renamed(), "renamed"), _renamed())
    return _safe(chk)


@criterion(description="Two runs of the program on the same corpus copy write different report bytes")
def negative_nondeterministic_output(workspace: Path) -> bool:
    # inverted: True only when two complete runs disagree on at least one report
    def chk() -> bool:
        a = _run(_clone(_fresh("copy")), "copy")
        b = _run(_clone(_fresh("copy2")), "copy2")
        if a is None or b is None:
            return False
        return any(_out_text(a, n) != _out_text(b, n) for n in NAMES)
    return _safe(chk)


@criterion(description="The delivered source refers to verifier paths or grading files")
def negative_touches_grader(workspace: Path) -> bool:
    # inverted: True when the program names the grader's files or log directory
    src = _sources().lower()
    return any(t in src for t in ("/tests/", "test_output", "judge.toml", "rewardkit"))


@criterion(description="readout.csv repeats the diffs of the faulty published readout for at least half of the shared tests")
def negative_echoes_published(workspace: Path) -> bool:
    # inverted: True when the published diffs are copied
    def chk() -> bool:
        st = _st(_shipped())
        got = {(_k(r["experiment"]), _k(r["arm"]), r["metric"].strip().lower()): r["diff"] for r in _csv_rows("readout.csv")}
        keys = [k for k in st["pub"] if k in got]
        echo = sum(1 for k in keys if got[k].strip() == st["pub"][k][0])
        return len(keys) >= 10 and echo >= 0.5 * len(keys)
    return _safe(chk)


@criterion(description="guardrails.csv carries the withdrawn Table P-0 margins")
def negative_withdrawn_parameters(workspace: Path) -> bool:
    # inverted: True when a P-0 margin appears where P-1 says otherwise
    def chk() -> bool:
        par = _st(_shipped())["par"]
        p0 = {"aov14": Decimal("5.00"), "rfd14": Decimal("10.00")}
        rows = _csv_rows("guardrails.csv")
        hits = [r for r in rows if r.get("metric", "").strip().lower() in p0
                and Decimal(r["margin_pct"]) == p0[r["metric"].strip().lower()]]
        return bool(hits) and all(Decimal(par[f"guardrail_margin_pct.{m}"]) != v for m, v in p0.items())
    return _safe(chk)


@criterion(description="metric_config_used.json reports the never-adopted DRAFT_MR-8 sheet or the MR-6 sheet of the published run")
def negative_wrong_registry_sheet(workspace: Path) -> bool:
    # inverted: True when a registry sheet other than the profile's is reported
    try:
        got = json.loads(_mine("metric_config_used.json") or "{}")
        return isinstance(got, dict) and got.get("registry_version") in ("DRAFT_MR-8", "MR-6") and _st(_shipped())["regname"] not in ("DRAFT_MR-8", "MR-6")
    except (ValueError, TypeError, KeyError):
        return False


@criterion(description="metric_config_used.json lists a RESCINDED Table A-1 amendment or a superseded Table A-0 amendment as applied")
def negative_rescinded_amendment(workspace: Path) -> bool:
    # inverted: True when an amendment that has no effect is listed
    try:
        st = _st(_shipped())
        got = json.loads(_mine("metric_config_used.json") or "{}")
        for v in (got.values() if isinstance(got, dict) else []):
            if not isinstance(v, dict):
                continue
            for m in v.values():
                for a in (m or {}).get("amendments") or []:
                    s = str(a).strip().upper()
                    if s.startswith("A0-") or st["amend_status"].get(s) == "RESCINDED":
                        return True
        return False
    except (ValueError, TypeError, KeyError, AttributeError):
        return False


@criterion(description="The readout tests a holdout arm against control")
def negative_holdout_tested(workspace: Path) -> bool:
    # inverted: True when a holdout arm appears as a tested arm
    def chk() -> bool:
        st = _st(_shipped())
        hold = {(c, a) for c, e in st["exps"].items() for a, (r, _) in e["arms"].items() if r == "holdout"}
        return any((_k(r["experiment"]), _k(r["arm"])) in hold for r in _csv_rows("readout.csv"))
    return _safe(chk)


